--
-- Table structure for table `requests`
--

DROP TABLE IF EXISTS `requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `requests` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `folio` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `public_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_type_id` bigint NOT NULL,
  `event_date` date NOT NULL,
  `event_time` time DEFAULT NULL,
  `guests` int NOT NULL,
  `duration_hours` int NOT NULL,
  `location` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'BASE',
  `extra_bartenders` int NOT NULL DEFAULT '0',
  `base_amount` decimal(12,2) NOT NULL,
  `premium_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `personal_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(12,2) NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDIENTE',
  `client_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `client_email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `client_whatsapp` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `client_id` bigint DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `bartenders` int NOT NULL DEFAULT '1',
  `assistants` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_requests_folio` (`folio`),
  UNIQUE KEY `uq_requests_token` (`public_token`),
  KEY `fk_requests_event_type` (`event_type_id`),
  KEY `fk_requests_client` (`client_id`),
  CONSTRAINT `fk_requests_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_requests_event_type` FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

